function plusDays(d,n){const t=new Date(d+'T00:00:00Z');t.setUTCDate(t.getUTCDate()+n);return t.toISOString().slice(0,10);}
function pctOn(rates, date) {
  let best = null;
  for (const r of rates) {
    if (r.from !== null && (date === null || r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to != null && date !== null && best.to < date) return null;
  return best?.pct ?? null;
}
function effectiveRates(own, inherited) {
  if (inherited.every((l) => l.length === 0)) return [...own];
  const levels = [own, ...inherited];
  const grades = [...new Set(levels.flatMap((l) => l.map((r) => r.grade)))].sort();
  const out = [];
  for (const grade of grades) {
    const byLevel = levels.map((l) => l.filter((r) => r.grade === grade));
    const cuts = new Set();
    for (const l of byLevel) for (const r of l) { if (r.from !== null) cuts.add(r.from); if (r.to !== null) cuts.add(plusDays(r.to, 1)); }
    const starts = [null, ...[...cuts].sort()];
    starts.forEach((start, i) => {
      const next = starts[i + 1] ?? null;
      const end = next === null ? null : plusDays(next, -1);
      const on = start ?? end ?? '1970-01-01';
      for (const l of byLevel) { const pct = pctOn(l, on); if (pct !== null) { out.push({ grade, from: start, to: end, pct }); break; } }
    });
  }
  return out;
}
const own=[{grade:'A',from:null,to:null,pct:'10.00'},{grade:'A',from:'2026-03-16',to:'2026-03-25',pct:'12.50'}];
const par=[{grade:'A',from:null,to:null,pct:'12.50'}];
const e=effectiveRates(own,[par]);console.log(e, pctOn(e,'2026-04-01'), pctOn(e,'2026-04-18'));
EOF
node t.mjs

